script:
app.beginUndoGroup("Pixelate Transition Out");
var comp = app.project.activeItem;
if (!(comp instanceof CompItem)) throw new Error("Open a composition first.");
if (comp.numLayers < 1) throw new Error("The active composition has no layers.");
var indexArray = [];
for (var i = 1; i <= comp.numLayers; i++) {
  indexArray.push(i);
}
comp.layers.precompose(indexArray, "PIXELATE OUT - CONTENT", true);
var controlsLayer = comp.layers.addNull(comp.duration);
controlsLayer.name = "PIXELATE OUT - CONTROLS";
controlsLayer.guideLayer = true;
var controls = controlsLayer.property("ADBE Effect Parade");
var progress = controls.addProperty("ADBE Slider Control");
progress.name = "Progress";
var progressStart = Math.max(0, comp.duration - 1);
var progressEnd = comp.duration;
progress.property(1).setValueAtTime(progressStart, 0);
progress.property(1).setValueAtTime(progressEnd, 100);
var maxBlockSize = controls.addProperty("ADBE Slider Control");
maxBlockSize.name = "Max Block Size";
maxBlockSize.property(1).setValue(48);
var sharpColors = controls.addProperty("ADBE Checkbox Control");
sharpColors.name = "Sharp Colors";
sharpColors.property(1).setValue(0);
var fadeOut = controls.addProperty("ADBE Checkbox Control");
fadeOut.name = "Fade Out";
fadeOut.property(1).setValue(1);
function quoteLayerName(value) {
  var result = "";
  for (var i = 0; i < value.length; i++) {
    var ch = value.charAt(i);
    if (ch === "\\" || ch === "'") result += "\\";
    result += ch;
  }
  return result;
}
var escapedControlsName = quoteLayerName(controlsLayer.name);
var contentLayer = comp.layer("PIXELATE OUT - CONTENT");
var contentEffects = contentLayer.property("ADBE Effect Parade");
var mosaic = contentEffects.addProperty("ADBE Mosaic");
var horizontalBlocks = mosaic.property("ADBE Mosaic-0001");
horizontalBlocks.expression = "var c = thisComp.layer('" + escapedControlsName + "');\nvar p = c.effect('Progress')('Slider');\nvar endBlocks = Math.max(1, Math.round(thisComp.width / Math.max(1, c.effect('Max Block Size')('Slider'))));\nMath.round(linear(p, 0, 100, thisComp.width, endBlocks));";
var verticalBlocks = mosaic.property("ADBE Mosaic-0002");
verticalBlocks.expression = "var c = thisComp.layer('" + escapedControlsName + "');\nvar p = c.effect('Progress')('Slider');\nvar endBlocks = Math.max(1, Math.round(thisComp.height / Math.max(1, c.effect('Max Block Size')('Slider'))));\nMath.round(linear(p, 0, 100, thisComp.height, endBlocks));";
var mosaicSharpColors = mosaic.property("ADBE Mosaic-0003");
mosaicSharpColors.expression = "var c = thisComp.layer('" + escapedControlsName + "');\nc.effect('Sharp Colors')('Checkbox');";
var blockDissolve = contentEffects.addProperty("ADBE Block Dissolve");
var transitionCompletion = blockDissolve.property("ADBE Block Dissolve-0001");
transitionCompletion.expression = "var p = thisComp.layer('" + escapedControlsName + "').effect('Progress')('Slider');\nlinear(p, 50, 100, 0, 100);";
var blockWidth = blockDissolve.property("ADBE Block Dissolve-0002");
blockWidth.expression = "var c = thisComp.layer('" + escapedControlsName + "');\nc.effect('Max Block Size')('Slider');";
var blockHeight = blockDissolve.property("ADBE Block Dissolve-0003");
blockHeight.expression = "var c = thisComp.layer('" + escapedControlsName + "');\nc.effect('Max Block Size')('Slider');";
blockDissolve.property("ADBE Block Dissolve-0004").setValue(0);
blockDissolve.property("ADBE Block Dissolve-0005").setValue(0);
var opacity = contentLayer.property("ADBE Transform Group").property("ADBE Opacity");
opacity.expression = "var c = thisComp.layer('" + escapedControlsName + "');\nvar p = c.effect('Progress')('Slider');\nvar fade = c.effect('Fade Out')('Checkbox');\nif (fade > 0) {\n  linear(p, 70, 100, 100, 0);\n} else {\n  100;\n}";
app.endUndoGroup();
